//! The channel-neutral attention payload and its field allowlist.
//!
//! The payload is the one decision a later delivery channel cannot undo without
//! touching every trigger, so it carries identifiers, closed states, an instant,
//! one deep link and short plain text — never Teams card markup, HTML, mention
//! syntax or a channel-specific field. Formatting belongs to the delivery
//! adapter at the edge.
//!
//! Every field is either a typed Kontor identifier or a closed vocabulary
//! value. `title` and `body` are generated by the trigger from already-normalized
//! receipt and task fields; there is deliberately no field a model output could
//! occupy, and both are rejected if they contain markup.
//!
//! The session-content boundary is **structural**, not a content classifier:
//! the payload has no transcript, prompt, assistant response or tool-result
//! member, and the only free text is the trigger's short title/body. The length
//! and character rules below keep those two fields from becoming destination
//! markup; they do not scan prose for session content and must not be presented
//! as if they did.

use kontor_core::id::{
    CommandReceiptId, ExternalName, MiniProjectId, ProjectId, RealmId, RoleKey, TaskId, Timestamp,
};
use kontor_core::receipt::CommandKind;
use kontor_core::state::TaskState;
use serde::{Deserialize, Serialize};

/// The closed attention kinds Kontor may emit.
///
/// Raw agent attention (a permission request or a finished turn) is deliberately
/// absent: Paseo's native push owns it (REQ-004).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum AlertKind {
    /// A task moved into `blocked`.
    TaskBlocked,
    /// A task moved into `parked`.
    TaskParked,
    /// A task moved into `needs_human`.
    TaskNeedsHuman,
    /// A task moved into `failed`.
    TaskFailed,
    /// An abandon receipt was born confirmed.
    CommandConfirmed,
    /// A seat holds a pending permission.
    WaitingSeatPendingPermission,
    /// A seat is observed waiting for input while its task is open.
    WaitingSeatWaitingInput,
    /// A seat reports running with no progress inside the staleness bound.
    WaitingSeatStalled,
    /// A hold passed its review date.
    HoldReviewOverdue,
}

impl AlertKind {
    /// The stable wire spelling.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::TaskBlocked => "task_blocked",
            Self::TaskParked => "task_parked",
            Self::TaskNeedsHuman => "task_needs_human",
            Self::TaskFailed => "task_failed",
            Self::CommandConfirmed => "command_confirmed",
            Self::WaitingSeatPendingPermission => "waiting_seat_pending_permission",
            Self::WaitingSeatWaitingInput => "waiting_seat_waiting_input",
            Self::WaitingSeatStalled => "waiting_seat_stalled",
            Self::HoldReviewOverdue => "hold_review_overdue",
        }
    }

    /// Parse one configured kind, or reject it.
    #[must_use]
    pub fn parse(value: &str) -> Option<Self> {
        Some(match value {
            "task_blocked" => Self::TaskBlocked,
            "task_parked" => Self::TaskParked,
            "task_needs_human" => Self::TaskNeedsHuman,
            "task_failed" => Self::TaskFailed,
            "command_confirmed" => Self::CommandConfirmed,
            "waiting_seat_pending_permission" => Self::WaitingSeatPendingPermission,
            "waiting_seat_waiting_input" => Self::WaitingSeatWaitingInput,
            "waiting_seat_stalled" => Self::WaitingSeatStalled,
            "hold_review_overdue" => Self::HoldReviewOverdue,
            _ => return None,
        })
    }

    /// The task state that raises this kind, when it is a task-state kind.
    #[must_use]
    pub const fn task_state(self) -> Option<TaskState> {
        match self {
            Self::TaskBlocked => Some(TaskState::Blocked),
            Self::TaskParked => Some(TaskState::Parked),
            Self::TaskNeedsHuman => Some(TaskState::NeedsHuman),
            Self::TaskFailed => Some(TaskState::Failed),
            _ => None,
        }
    }

    /// Whether this is the last-resort human-attention kind.
    ///
    /// `needs_human` is never suppressed by configuration.
    #[must_use]
    pub const fn is_unsuppressible(self) -> bool {
        matches!(self, Self::TaskNeedsHuman)
    }
}

/// How urgently the operator should look.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Severity {
    /// Recorded, no action implied.
    Info,
    /// A decision or recovery is expected.
    Warning,
    /// The last-resort human-attention case, or a failed work item.
    Critical,
}

/// The closed resulting-state vocabulary a payload may name.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ResultingState {
    /// Task state `blocked`.
    Blocked,
    /// Task state `parked`.
    Parked,
    /// Task state `needs_human`.
    NeedsHuman,
    /// Task state `failed`.
    Failed,
    /// A receipt settled confirmed.
    Confirmed,
    /// A seat holds a pending permission.
    PendingPermission,
    /// A seat is observed waiting for input.
    WaitingInput,
    /// A seat reports running without progress.
    Stalled,
    /// A hold passed its review date.
    HoldReviewOverdue,
}

impl ResultingState {
    /// The stable wire spelling.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Blocked => "blocked",
            Self::Parked => "parked",
            Self::NeedsHuman => "needs_human",
            Self::Failed => "failed",
            Self::Confirmed => "confirmed",
            Self::PendingPermission => "pending_permission",
            Self::WaitingInput => "waiting_input",
            Self::Stalled => "stalled",
            Self::HoldReviewOverdue => "hold_review_overdue",
        }
    }
}

/// The longest plain-text title the payload accepts.
pub const MAX_TITLE: usize = 160;
/// The longest plain-text body the payload accepts.
pub const MAX_BODY: usize = 600;
/// The longest deep link the payload accepts.
pub const MAX_DEEP_LINK: usize = 2048;

/// Why a payload was refused.
#[derive(Debug, thiserror::Error)]
#[non_exhaustive]
pub enum PayloadError {
    /// The document is not the closed attention shape.
    #[error("the attention payload is not the closed channel-neutral shape")]
    Shape,
    /// A structurally valid document violates one rule.
    #[error("the attention payload is invalid: {rule}")]
    Invalid {
        /// The stable rule, never a configured value.
        rule: &'static str,
    },
}

/// One channel-neutral alert.
///
/// The field list is the allowlist: realm, project, epic/task, seat role,
/// command kind, receipt, resulting state, instant, one deep link, severity and
/// short plain text. `deny_unknown_fields` makes a transcript-shaped field
/// impossible to smuggle in through a deserializer.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AttentionPayload {
    /// Schema generation of this payload.
    pub schema_version: u32,
    /// What happened, from the closed Kontor vocabulary.
    pub kind: AlertKind,
    /// How urgently the operator should look.
    pub severity: Severity,
    /// Owning Realm.
    pub realm_id: RealmId,
    /// Owning project.
    pub project_id: ProjectId,
    /// Owning epic, when the alert names one.
    pub mini_project_id: Option<MiniProjectId>,
    /// The task, when the alert names one.
    pub task_id: Option<TaskId>,
    /// The seat/role code that owns or last worked the task.
    pub seat: RoleKey,
    /// The command kind, when the alert names a receipt.
    pub command_kind: Option<CommandKind>,
    /// The receipt, when the alert names one.
    pub receipt_id: Option<CommandReceiptId>,
    /// The settled state that raised the alert.
    pub resulting_state: ResultingState,
    /// When the state settled.
    pub occurred_at: Timestamp,
    /// One link that opens the thing the alert is about.
    pub deep_link: String,
    /// Short plain-text title.
    pub title: String,
    /// Short plain-text body.
    pub body: String,
}

impl AttentionPayload {
    /// Build and validate one payload.
    ///
    /// # Errors
    /// Returns [`PayloadError::Invalid`] naming a stable rule when a bound or
    /// plain-text rule is violated.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        kind: AlertKind,
        severity: Severity,
        realm_id: RealmId,
        project_id: ProjectId,
        mini_project_id: Option<MiniProjectId>,
        task_id: Option<TaskId>,
        seat: RoleKey,
        command_kind: Option<CommandKind>,
        receipt_id: Option<CommandReceiptId>,
        resulting_state: ResultingState,
        occurred_at: Timestamp,
        deep_link: String,
        title: String,
        body: String,
    ) -> Result<Self, PayloadError> {
        let payload = Self {
            schema_version: 1,
            kind,
            severity,
            realm_id,
            project_id,
            mini_project_id,
            task_id,
            seat,
            command_kind,
            receipt_id,
            resulting_state,
            occurred_at,
            deep_link,
            title,
            body,
        };
        payload.validate()?;
        Ok(payload)
    }

    /// Validate every allowlist, bound and plain-text rule.
    ///
    /// # Errors
    /// Returns [`PayloadError::Invalid`] naming the first rule that failed.
    pub fn validate(&self) -> Result<(), PayloadError> {
        if self.schema_version != 1 {
            return invalid("schema_version must be 1");
        }
        plain_text("title", &self.title, MAX_TITLE)?;
        plain_text("body", &self.body, MAX_BODY)?;
        if self.deep_link.is_empty()
            || self.deep_link.len() > MAX_DEEP_LINK
            || self.deep_link.chars().any(char::is_whitespace)
            || self.deep_link.chars().any(char::is_control)
            || self.deep_link.contains('@')
        {
            return invalid(
                "deep_link is one bounded link without whitespace, control characters or userinfo",
            );
        }
        if !(self.deep_link.starts_with("paseo://")
            || self.deep_link.starts_with("http://")
            || self.deep_link.starts_with("https://"))
        {
            return invalid("deep_link must be a paseo, http or https link");
        }
        if self.kind.task_state().is_some() && self.task_id.is_none() {
            return invalid("a task-state alert must name its task");
        }
        if self.kind == AlertKind::CommandConfirmed && self.receipt_id.is_none() {
            return invalid("a command alert must name its receipt");
        }
        if self.kind == AlertKind::HoldReviewOverdue && self.mini_project_id.is_none() {
            return invalid("a hold alert must name its epic");
        }
        // Every alert names a seat; `team_run` and `operator` are explicit
        // role codes, never an absent field (REQ-005).
        Ok(())
    }

    /// Prove this payload is the closed attention shape and nothing else.
    ///
    /// This is the `ensure_no_session_content` boundary for the attention
    /// channel: the serialized document may contain exactly the allowlisted
    /// fields, each a scalar, and no nested shape that could carry a transcript.
    ///
    /// # Errors
    /// Returns [`PayloadError::Shape`] for any extra or nested member and
    /// [`PayloadError::Invalid`] when a text bound is violated.
    pub fn ensure_no_session_content(&self) -> Result<(), PayloadError> {
        self.validate()?;
        let document = serde_json::to_value(self).map_err(|_| PayloadError::Invalid {
            rule: "the payload could not be serialized",
        })?;
        let serde_json::Value::Object(members) = document else {
            return Err(PayloadError::Shape);
        };
        const ALLOWED: &[&str] = &[
            "schema_version",
            "kind",
            "severity",
            "realm_id",
            "project_id",
            "mini_project_id",
            "task_id",
            "seat",
            "command_kind",
            "receipt_id",
            "resulting_state",
            "occurred_at",
            "deep_link",
            "title",
            "body",
        ];
        if members.len() != ALLOWED.len() {
            return Err(PayloadError::Shape);
        }
        for (key, value) in &members {
            if !ALLOWED.contains(&key.as_str()) {
                return Err(PayloadError::Shape);
            }
            if matches!(
                value,
                serde_json::Value::Array(_) | serde_json::Value::Object(_)
            ) {
                return Err(PayloadError::Shape);
            }
        }
        Ok(())
    }

    /// Parse one document through the closed shape, for boundary tests.
    ///
    /// # Errors
    /// Returns [`PayloadError::Shape`] for an unknown field or a non-scalar
    /// member, and the [`PayloadError::Invalid`] rule when a value is refused.
    pub fn from_document(document: &str) -> Result<Self, PayloadError> {
        let payload: Self = serde_json::from_str(document).map_err(|_| PayloadError::Shape)?;
        payload.ensure_no_session_content()?;
        Ok(payload)
    }

    /// The author name a destination adapter adds, as plain text.
    #[must_use]
    pub fn summary(&self) -> String {
        format!(
            "{}: {} ({})",
            self.kind.as_str(),
            self.title,
            self.resulting_state.as_str()
        )
    }
}

fn invalid<T>(rule: &'static str) -> Result<T, PayloadError> {
    Err(PayloadError::Invalid { rule })
}

fn plain_text(field: &'static str, value: &str, limit: usize) -> Result<(), PayloadError> {
    if value.trim().is_empty() {
        return Err(PayloadError::Invalid {
            rule: match field {
                "title" => "title must be non-empty plain text",
                _ => "body must be non-empty plain text",
            },
        });
    }
    if value.chars().count() > limit {
        return Err(PayloadError::Invalid {
            rule: match field {
                "title" => "title exceeds the plain-text bound",
                _ => "body exceeds the plain-text bound",
            },
        });
    }
    if value
        .chars()
        .any(|character| is_markdown_control(character) || character.is_control())
    {
        return Err(PayloadError::Invalid {
            rule: match field {
                "title" => "title carries channel markup or a control character",
                _ => "body carries channel markup or a control character",
            },
        });
    }
    Ok(())
}

fn is_markdown_control(character: char) -> bool {
    matches!(
        character,
        '<' | '>'
            | '@'
            | '\\'
            | '`'
            | '*'
            | '['
            | ']'
            | '('
            | ')'
            | '#'
            | '|'
            | '~'
            | '!'
            | '$'
            | '{'
            | '}'
    )
}

/// Render one normalized task title as plain payload text, or omit it.
///
/// `ExternalName` is already normalized, but a title may still contain a
/// character the destination adapter would read as markup. Replacing it is
/// safer than refusing the alert the operator needs.
#[must_use]
pub fn plain_task_title(title: &ExternalName) -> String {
    let text: String = title
        .as_str()
        .chars()
        .map(|character| {
            if is_markdown_control(character) || character.is_control() {
                ' '
            } else {
                character
            }
        })
        .collect();
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn payload() -> AttentionPayload {
        AttentionPayload::new(
            AlertKind::TaskNeedsHuman,
            Severity::Critical,
            RealmId::generate(),
            ProjectId::generate(),
            Some(MiniProjectId::generate()),
            Some(TaskId::generate()),
            RoleKey::parse("harness-seat").expect("a seat"),
            None,
            None,
            ResultingState::NeedsHuman,
            Timestamp::now(),
            format!(
                "http://127.0.0.1:7717/v1/projects/{}/tasks/{}",
                ProjectId::generate(),
                TaskId::generate()
            ),
            "Task needs a human".to_owned(),
            "The task entered needs_human.".to_owned(),
        )
        .expect("a valid payload")
    }

    #[test]
    fn the_payload_is_channel_neutral() {
        let payload = payload();
        let document = serde_json::to_string(&payload).expect("serializes");
        for forbidden in ["<", ">", "@", "<at>", "<!channel>", "[", "]", "*", "`"] {
            assert!(!document.contains(forbidden), "{forbidden} in {document}");
        }
        for forbidden in ['$', '{', '}'] {
            assert!(!payload.title.contains(forbidden));
            assert!(!payload.body.contains(forbidden));
        }
        payload
            .ensure_no_session_content()
            .expect("the closed shape is safe");
    }

    #[test]
    fn a_transcript_shaped_member_is_refused() {
        let mut document = serde_json::to_value(payload()).expect("serializes");
        document.as_object_mut().expect("an object").insert(
            "transcript".to_owned(),
            serde_json::json!([{"role": "assistant", "text": "secret"}]),
        );
        let refused = AttentionPayload::from_document(&document.to_string());
        assert!(matches!(refused, Err(PayloadError::Shape)));
    }

    #[test]
    fn markup_and_prose_bounds_are_refused() {
        let mut value = payload();
        value.body = "assistant: here is the transcript".repeat(30);
        assert!(value.ensure_no_session_content().is_err());

        let mut value = payload();
        value.title = "<at>operator</at>".to_owned();
        assert!(value.validate().is_err());

        let mut value = payload();
        value.title = "[click](https://example)".to_owned();
        assert!(value.validate().is_err());

        let mut value = payload();
        value.body = "**bold**".to_owned();
        assert!(value.validate().is_err());

        let mut value = payload();
        value.body = "${secret}".to_owned();
        assert!(value.validate().is_err());
    }

    #[test]
    fn a_task_title_is_neutralized_before_it_reaches_the_payload() {
        let title =
            ExternalName::parse("Ship [x](https://example) **now**").expect("a normalized title");
        let plain = plain_task_title(&title);
        assert!(!plain.contains('['));
        assert!(!plain.contains('*'));
        assert!(!plain.contains('('));
        assert!(plain.contains("Ship"));
    }

    #[test]
    fn a_task_state_alert_must_name_its_task() {
        let mut payload = payload();
        payload.task_id = None;
        assert!(payload.validate().is_err());
    }
}
